class Solution:
    def greatestLetter(self, s: str) -> str:
        lo = set(s.lower())
        up = set(s)
        for c in 'ZYXWVUTSRQPONMLKJIHGFEDCBA':
            if c in up and c.lower() in lo:
                return c
        return ''

