class Solution {
public:
    string greatestLetter(string s) {
        bool lo[26] = {false}, up[26] = {false};
        for (char c : s) {
            if (islower(c)) lo[c - 'a'] = true;
            else up[c - 'A'] = true;
        }
        for (int i = 25; i >= 0; i--)
            if (lo[i] && up[i]) return string(1, 'A' + i);
        return "";
    }
};

c.java:
class Solution {
    public String greatestLetter(String s) {
        boolean[] lo = new boolean[26], up = new boolean[26];
        for (char c : s.toCharArray()) {
            if (Character.isLowerCase(c)) lo[c - 'a'] = true;
            else up[c - 'A'] = true;
        }
        for (int i = 25; i >= 0; i--)
            if (lo[i] && up[i]) return String.valueOf((char) ('A' + i));
        return "";
    }
}

c.javascript:
var greatestLetter = function(s) {
    const lo = new Set(), up = new Set();
    for (const c of s) {
        if (c >= 'a' && c <= 'z') lo.add(c);
        else up.add(c);
    }
    for (let i = 25; i >= 0; i--) {
        const u = String.fromCharCode(65 + i), l = String.fromCharCode(97 + i);
        if (up.has(u) && lo.has(l)) return u;
    }
    return '';
};
